data: ReferenceEntityTemplateSchema = {
  name: 'App',
  overviewPreviewDescription: 'Retrieve extension status and activation details',
  description: `The App API provides read-only access to extension information through the \`app.extensions()\` method, enabling discovery of installed extensions and their activation status. The method asynchronously retrieves detailed information including handles, types, and activations across different surfaces.

The method returns a Promise that resolves to an array of \`ExtensionInfo\` objects. Each object contains:
- \`handle\`: The unique identifier for the extension
- \`type\`: Either \`'ui_extension'\` or \`'theme_app_extension'\`
- \`activations\`: Activation records (shape varies by extension type)

The array may be empty if the app has no extensions.

**UI extensions** have activations with a \`target\` field indicating the admin, checkout, customer account or point of sale target.

**Theme app extensions** have activations representing individual blocks/embeds, each with:
- \`handle\`: Block/embed filename
- \`name\`: Display name from block schema
- \`target\`: Location type (\`'section'\`, \`'head'\`, \`'body'\`, or \`'compliance_head'\`)
- \`status\`: Availability status (\`'active'\`, \`'available'\`, or \`'unavailable'\`)
- \`activations\`: Array of theme-specific placements with \`target\` and \`themeId\`

> Note: For [theme app extensions](/docs/apps/build/online-store/theme-app-extensions), activation data is sourced from the store's published theme only.`,
  isVisualComponent: false,
  category: 'APIs',
  subCategory: 'Authentication and data',
  related: [],
  defaultExample: {
    description:
      'Retrieve extension information. This example fetches all installed extensions, returning an array with UI and theme app extension data.',
    codeblock: {
      title: 'Get extension status',
      tabs: [
        {
          code: '../examples/app/extensions.js',
          language: 'js',
        },
      ],
    },
  },
  examples: {
    description: 'Examples for working with extension data.',
    exampleGroups: [
      {
        title: '',
        examples: [
          {
            description:
              'Filter extensions by type. This example separates UI extensions from theme app extensions, which have different activation structures. Useful for checking admin targets vs storefront placements.',
            codeblock: {
              title: 'Get extension status and filter by type',
              tabs: [
                {
                  code: '../examples/app/filter-by-type.js',
                  language: 'js',
                },
              ],
            },
          },
        ],
      },
    ],
  },
  definitions: [
    {
      title: 'Methods',
      description: `The \`app\` API is available on the \`shopify\` global object. The \`extensions\` method is asynchronous and returns a Promise that resolves to an array of \`ExtensionInfo\` objects.`,
      type: 'AppApi',
    },
  ],
}

